-- KVN Weddings & Conventions production schema (API-free Muhurtham database)
create extension if not exists pgcrypto;
create table if not exists public.manager_profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null,role text not null default 'manager' check(role in('admin','manager')),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.calendar_dates(date date primary key,morning_status text not null default 'available' check(morning_status in('available','booked')),evening_status text not null default 'available' check(evening_status in('available','booked')),auspicious boolean not null default false,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table if not exists public.booking_details(id uuid primary key default gen_random_uuid(),date date not null references public.calendar_dates(date) on delete cascade,slot text not null check(slot in('morning','evening')),event_name text,customer_name text,customer_phone text,manager_notes text,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(date,slot));
create table if not exists public.enquiries(id uuid primary key default gen_random_uuid(),event_date date not null,slot text not null check(slot in('Morning','Evening','Full Day')),name text not null,phone text not null,email text,event_type text not null,guest_count integer,message text,status text not null default 'new',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ begin if exists(select 1 from pg_constraint where conname='enquiries_status_check' and conrelid='public.enquiries'::regclass) then alter table public.enquiries drop constraint enquiries_status_check; end if; alter table public.enquiries add constraint enquiries_status_check check(status in('new','contacted','advance_paid','declined','confirmed')); exception when duplicate_object then null; end $$;
create table if not exists public.muhurtham_dates(date date primary key,is_muhurtham boolean not null default true,source text not null default 'Published public marriage-muhurtham calendars',source_reference text,admin_override boolean,admin_note text,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());

-- Compatibility migration: the KVN project may already have an older muhurtham_dates table.
-- Add every column used by the current website/admin before loading the 2026-2040 dataset.
alter table public.muhurtham_dates add column if not exists source_reference text;
alter table public.muhurtham_dates add column if not exists admin_override boolean;
alter table public.muhurtham_dates add column if not exists admin_note text;
alter table public.muhurtham_dates add column if not exists updated_by uuid references auth.users(id);
alter table public.muhurtham_dates add column if not exists updated_at timestamptz not null default now();
alter table public.muhurtham_dates add column if not exists score numeric;
alter table public.muhurtham_dates add column if not exists start_time time;
alter table public.muhurtham_dates add column if not exists end_time time;
alter table public.muhurtham_dates add column if not exists panchanga jsonb;
alter table public.muhurtham_dates add column if not exists generated_at timestamptz not null default now();
create index if not exists muhurtham_dates_year_idx on public.muhurtham_dates(date);
create index if not exists enquiries_created_idx on public.enquiries(created_at desc);
create index if not exists enquiries_date_idx on public.enquiries(event_date);
create index if not exists booking_details_date_idx on public.booking_details(date);
create or replace function public.is_manager() returns boolean language sql security definer set search_path=public stable as $$ select exists(select 1 from public.manager_profiles where user_id=auth.uid() and active=true); $$;
alter table public.manager_profiles enable row level security; alter table public.calendar_dates enable row level security; alter table public.booking_details enable row level security; alter table public.enquiries enable row level security; alter table public.muhurtham_dates enable row level security;
drop policy if exists public_calendar_read on public.calendar_dates; create policy public_calendar_read on public.calendar_dates for select to anon,authenticated using(true);
drop policy if exists manager_calendar_insert on public.calendar_dates; create policy manager_calendar_insert on public.calendar_dates for insert to authenticated with check(public.is_manager());
drop policy if exists manager_calendar_update on public.calendar_dates; create policy manager_calendar_update on public.calendar_dates for update to authenticated using(public.is_manager()) with check(public.is_manager());
drop policy if exists manager_profile_read on public.manager_profiles; create policy manager_profile_read on public.manager_profiles for select to authenticated using(user_id=auth.uid() or public.is_manager());
drop policy if exists manager_booking_read on public.booking_details; create policy manager_booking_read on public.booking_details for select to authenticated using(public.is_manager());
drop policy if exists manager_booking_insert on public.booking_details; create policy manager_booking_insert on public.booking_details for insert to authenticated with check(public.is_manager());
drop policy if exists manager_booking_update on public.booking_details; create policy manager_booking_update on public.booking_details for update to authenticated using(public.is_manager()) with check(public.is_manager());
drop policy if exists public_enquiry_insert on public.enquiries; create policy public_enquiry_insert on public.enquiries for insert to anon,authenticated with check(true);
drop policy if exists manager_enquiry_read on public.enquiries; create policy manager_enquiry_read on public.enquiries for select to authenticated using(public.is_manager());
drop policy if exists manager_enquiry_update on public.enquiries; create policy manager_enquiry_update on public.enquiries for update to authenticated using(public.is_manager()) with check(public.is_manager());
drop policy if exists public_muhurtham_read on public.muhurtham_dates; create policy public_muhurtham_read on public.muhurtham_dates for select to anon,authenticated using(true);
drop policy if exists manager_muhurtham_update on public.muhurtham_dates; create policy manager_muhurtham_update on public.muhurtham_dates for update to authenticated using(public.is_manager()) with check(public.is_manager());
drop policy if exists manager_muhurtham_insert on public.muhurtham_dates; create policy manager_muhurtham_insert on public.muhurtham_dates for insert to authenticated with check(public.is_manager());
-- Realtime: ignore duplicate errors if publication/table is already configured.
do $$ begin alter publication supabase_realtime add table public.enquiries; exception when duplicate_object then null; end $$;
do $$ begin alter publication supabase_realtime add table public.calendar_dates; exception when duplicate_object then null; end $$;

-- Source-verified seed database, 2026-2040. Availability is NOT included here.
